"""Database engine, session factory and declarative base."""

import os
from collections.abc import Iterator
from typing import Any

from sqlalchemy import create_engine, event
from sqlalchemy.orm import DeclarativeBase, Session, sessionmaker

DATABASE_URL = os.getenv("DATABASE_URL", "sqlite:///./app.db")

_connect_args = {"check_same_thread": False} if DATABASE_URL.startswith("sqlite") else {}
engine = create_engine(DATABASE_URL, connect_args=_connect_args, pool_pre_ping=True)
SessionLocal = sessionmaker(bind=engine, autoflush=False, expire_on_commit=False)

if DATABASE_URL.startswith("sqlite"):

    @event.listens_for(engine, "connect")
    def _enforce_foreign_keys(connection: Any, _record: Any) -> None:
        # SQLite ignores foreign keys (and ON DELETE CASCADE) unless this is on.
        connection.execute("PRAGMA foreign_keys=ON")


class Base(DeclarativeBase):
    pass


def get_session() -> Iterator[Session]:
    with SessionLocal() as session:
        yield session

"""Pydantic request/response schemas."""

from datetime import date, datetime

from pydantic import BaseModel, ConfigDict, Field, field_validator


class ProductCreate(BaseModel):
    name: str = Field(..., max_length=255)
    price: float = Field(...)
    stock: int = Field(...)
    active: bool = Field(...)


class ProductUpdate(BaseModel):
    name: str | None = Field(None, max_length=255)
    price: float | None = Field(None)
    stock: int | None = Field(None)
    active: bool | None = Field(None)

    @field_validator("name", "price", "stock", "active")
    @classmethod
    def _not_null(cls, value: object) -> object:
        if value is None:
            raise ValueError("may be omitted, but not set to null")
        return value


class ProductRead(ProductCreate):
    model_config = ConfigDict(from_attributes=True)

    id: int
    created_at: datetime


class ShipmentCreate(BaseModel):
    carrier: str = Field(..., max_length=255)
    shipped_at: datetime = Field(...)
    delivered_on: date | None = Field(None)
    notes: str | None = Field(None)


class ShipmentUpdate(BaseModel):
    carrier: str | None = Field(None, max_length=255)
    shipped_at: datetime | None = Field(None)
    delivered_on: date | None = Field(None)
    notes: str | None = Field(None)

    @field_validator("carrier", "shipped_at")
    @classmethod
    def _not_null(cls, value: object) -> object:
        if value is None:
            raise ValueError("may be omitted, but not set to null")
        return value


class ShipmentRead(ShipmentCreate):
    model_config = ConfigDict(from_attributes=True)

    id: int
    created_at: datetime

